# Get expanding colors (threshold >= 10)
def make_output(input_grid, threshold=10):
    h, w = len(input_grid), len(input_grid[0])
    output = [row[:] for row in input_grid]

    # First pass: find all expanding colors and their medians
    exp_colors = {}
    for c in range(10):
        if c == 0: continue

        cells = [(r, col_idx) for r in range(h) for col_idx in range(w) if input_grid[r][col_idx] == c]

        if len(cells) >= threshold:
            sorted_rows = sorted(set(r for r,_ in cells))
            sorted_cols = sorted(set(c for _,c_idx in cells))
            med_row = sorted_rows[len(sorted_rows)//2]
            med_col = sorted_cols[len(sorted_cols)//2]
            exp_colors[c] = {'median_r': med_row, 'median_c': med_col}

    print("Expanding colors:", exp_colors)

    # Apply: fill rows and cols, but preserve 0s at intersections
    for c in range(10):
        if c == 0 or c not in exp_colors:
            continue

        info = exp_colors[c]
        med_r, med_c = info['median_r'], info['median_c']

        # Fill row, but skip columns that are median cols of OTHER colors at origin 0
        for c_idx in range(w):
            new_val = c
            if input_grid[med_r][c_idx] == 0:
                # Check if this column is a median col of another color
                for other_c, other_info in exp_colors.items():
                    if other_c != c and c_idx == other_info['median_c']:
                        new_val = 0
            output[med_r][c_idx] = new_val

        # Fill column, but skip rows that are median rows of OTHER colors at origin 0
        for r in range(h):
            new_val = c
            if input_grid[r][med_c] == 0:
                for other_c, other_info in exp_colors.items():
                    if other_c != c and r == other_info['median_r']:
                        new_val = 0
            output[r][med_c] = new_val

    return output

