import json
from collections import deque

def parse_grid(text):
    lines = text.strip().split('\n')
    rows = []
    for line in lines:
        parts = line.split()
        if parts and all(x.isdigit() for x in parts):
            rows.append([int(x) for x in parts])
    return rows

def find_components(grid, color):
    visited = set()
    components = []
    h, w = len(grid), len(grid[0])

    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                yield (nr, nc)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r,c) not in visited:
                comp = [(r,c)]
                visited.add((r,c))
                q = deque([(r,c)])
                while q:
                    cur_r, cur_c = q.popleft()
                    for nr, nc in get_neighbors(cur_r, cur_c):
                        visited.add((nr, nc))
                        comp.append((nr, nc))
                        q.append((nr, nc))
                components.append(comp)
    return components

